/* ---------- Tegnefunktioner ---------- */
function esc(s) { return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
function kr(n) { return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, '.') + ' kr.'; }

function photoUrl(base, w) { return base + '?auto=format&fit=crop&w=' + w + '&q=70'; }
function photoTag(key, opts) {
  var ph = PHOTOS[key]; if (!ph) return '';
  opts = opts || {};
  var widths = opts.widths || [600, 1000, 1600];
  var w = opts.w || 1600, h = opts.h || 1200;
  var set = widths.map(function (x) { return photoUrl(ph.src, x) + ' ' + x + 'w'; }).join(', ');
  return '<!-- Foto: ' + esc(ph.by) + ' / Unsplash – ' + esc(ph.page) + ' -->' +
    '<img src="' + photoUrl(ph.src, widths[1] || widths[0]) + '" srcset="' + set + '" sizes="' + (opts.sizes || '(min-width: 900px) 60vw, 100vw') + '"' +
    ' width="' + w + '" height="' + h + '" alt="' + esc(opts.alt != null ? opts.alt : ph.alt) + '"' +
    (opts.eager ? ' fetchpriority="high"' : ' loading="lazy"') + ' decoding="async"' +
    ' style="object-position:' + esc(ph.pos) + '" onerror="this.parentNode.classList.add(\'is-missing\')">';
}

function renderProjects() {
  return PROJECTS.map(function (p, i) {
    var st = STATUS[p.status] || STATUS.dev;
    var mock = p.shot ? '<img class="mk-shot" src="' + esc(p.shot) + '" width="800" height="500" alt="' + esc(p.imageAlt) + '" loading="lazy" decoding="async">' : (MOCKUPS[p.image] ? MOCKUPS[p.image](p.imageAlt) : '');
    var phone = PHONES[p.image] ? PHONES[p.image]() : '';
    var demo = p.demoUrl ? '<p class="p-live"><a class="text-link" href="' + esc(p.demoUrl) + '" target="_blank" rel="noopener">' + (p.status === 'live' && !p.concept ? 'Se siden live' : 'Se konceptet') + '<span class="sr-only"> (åbner i en ny fane)</span> ↗</a></p>' : '';
    return '<li class="p-card p-card--' + esc(p.card || 'soft') + (p.wide ? ' p-card--wide' : '') + ' rv" style="--i:' + i + '" data-category="' + esc(p.category) + '" aria-labelledby="proj-' + esc(p.id) + '">' +
      '<figure class="project-media' + (p.shot ? ' project-media--shot' : '') + '">' +
        (p.photo ? '<div class="photo" aria-hidden="true">' + photoTag(p.photo, { alt: '', sizes: '(min-width: 768px) 45vw, 100vw', widths: [600, 1000] }) + '</div>' : '') +
        (p.demoUrl ? '<a class="mk-browser mk-link" href="' + esc(p.demoUrl) + '" target="_blank" rel="noopener" tabindex="-1" aria-hidden="true">' + mock + '</a>' : '<div class="mk-browser">' + mock + '</div>') +
        (phone ? '<div class="mk-phone" aria-hidden="true">' + phone + '</div>' : '') +
      '</figure>' +
      '<p class="sticker sticker--status ' + st.cls + '" style="--r:' + (i % 2 ? '-5deg' : '6deg') + '">' + (p.concept ? 'Koncept' : esc(st.label)) + '</p>' +
      '<h3 id="proj-' + esc(p.id) + '">' + esc(p.title) + '</h3>' +
      '<p class="p-cat">' + esc(p.categoryLabel) + '</p>' + ((p.shot || p.wide) ? '<p class="p-idea">' + esc(p.idea) + '</p>' : '') + demo +
    '</li>';
  }).join('');
}

function renderAddons() {
  // Én linje under prisen: "Tilvalg: hosting & support fra 300 kr./md., tekster, logo, ekstra sider."
  return '<strong>Tilvalg:</strong> ' + ADDONS.map(function (a) { return esc(a.short || a.name); }).join(', ') + '.';
}

/* ---------- Hero: ord der skifter + vifte af fire færdige konceptsider ----------
   HERO_WORDS skal passe med ordene i <span class="swap"> i index.html.
   Det sidste ord ("din virksomhed.") er hvileordet, som siden starter og slutter på. */
var HERO_WORDS = ['caféer.', 'tømrere.', 'frisører.', 'butikker.', 'fitnesscentre.', 'revisorer.', "VVS'ere.", 'klinikker.', 'foreninger.', 'restauranter.', 'hjemmeplejen.', 'din virksomhed.'];
var FAN = [
  { id: 'cafe',   logo: 'Café Havre',   h: 'Kaffe og kage hver dag',          btn: 'Se menukort', photo: 'cafe' },
  { id: 'tomrer', logo: 'Fjeld Tømrer', h: 'Tømrer, der møder op til tiden',  btn: 'Ring nu',     photo: 'tomrer' },
  { id: 'frisor', logo: 'Salon Saks',   h: 'Book din tid online',             btn: 'Book tid',    photo: 'salon' },
  { id: 'butik',  logo: 'Butik Lyng',   h: 'Nyt i butikken',                  btn: 'Se varer',    photo: null }
];
function renderSwap() {
  var rest = HERO_WORDS.length - 1;
  return HERO_WORDS.map(function (w, i) { return '<span' + (i === rest ? ' class="is-on"' : '') + '>' + esc(w) + '</span>'; }).join('');
}
function renderFan() {
  return FAN.map(function (f, i) {
    var ph = f.photo && PHOTOS[f.photo];
    return '<div class="fan-card fan-card--' + f.id + '" data-pos="' + i + '">' +
      '<div class="fc-bar"><i></i><i></i><i></i><span>' + esc(f.logo.toLowerCase().replace(/\s+/g, '-')) + ' · koncept</span></div>' +
      '<div class="fc-page"><b class="fc-logo">' + esc(f.logo) + '</b><p class="fc-h">' + esc(f.h) + '</p><span class="fc-btn">' + esc(f.btn) + '</span>' +
      '<span class="fc-img"' + (ph ? ' style="background-image:url(\'' + photoUrl(ph.src, 600) + '\')"' : '') + '></span></div></div>';
  }).join('');
}

