/* Punktummet i "Faste priser. Punktum." falder ned, når det ses, og hopper ved hover */
(function () {
  var d = document.querySelector('.pdot');
  if (!d) return;
  if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) { d.classList.add('is-dropped'); return; }
  if ('IntersectionObserver' in window) {
    var io = new IntersectionObserver(function (es) {
      if (es[0].isIntersecting) { setTimeout(function () { d.classList.add('is-dropped'); }, 250); io.disconnect(); }
    }, { threshold: 1 });
    io.observe(d);
  } else d.classList.add('is-dropped');
  var h2 = d.closest('h2');
  (h2 || d).addEventListener('mouseenter', function () {
    if (!d.classList.contains('is-dropped')) return;
    d.classList.remove('is-bounce'); void d.offsetWidth; d.classList.add('is-bounce');
  });
})();
